export function registrationView({state,topbar,icon,esc,button,covenant}){
 if(state.account)return `${topbar('我的账号')}<main class="main"><h1>已经认识你啦。</h1>${button('进入我的主页','public-profile','button primary full')}</main>`;
 return `${topbar('成为领养者','确认公约 → 语音访谈 → 确认注册')}<main class="main"><div class="join-hero"><span class="join-badge">${icon('heart')} 一起认真照顾它</span><h1>先认识你，<br>再一起遇见它。</h1><p>填写账号资料，确认公约后进入语音访谈。</p></div><form id="register-form" class="form-stack">${covenant}<label>主页昵称<input name="nickname" required maxlength="20" placeholder="你希望怎么被称呼" value="${esc(state.registrationDraft?.nickname||'')}" autocomplete="nickname"></label><label>登录账号<input name="username" required minlength="3" maxlength="64" pattern="[a-zA-Z](?:[a-zA-Z0-9._]|-){2,63}" placeholder="字母开头，3–64 位字母、数字或 . _ -" autocomplete="username" autocapitalize="none" spellcheck="false"></label><label>设置密码<input name="password" type="password" required minlength="12" maxlength="128" placeholder="至少 12 位" autocomplete="new-password"></label><label>真实姓名<input name="realName" required minlength="2" maxlength="50" autocomplete="name" placeholder="仅用于平台身份资料，不公开"></label><label>手机号<input name="phone" type="tel" required maxlength="20" inputmode="tel" autocomplete="tel" placeholder="用于后续领养联系"></label><details><summary>补充微信与邮箱（选填）</summary><label>微信号<input name="wechat" maxlength="40"></label><label>邮箱<input name="email" type="email" maxlength="100" autocomplete="email"></label></details><div class="identity-preview">${icon('shield')}<div><strong>身份信息不在个人主页公开</strong><p>账号创建后实名状态为待核验。手机号与身份核验服务尚未开通，当前不上传证件。救助站会看到待核验状态，身份核验完成前不能确认领养交接。</p></div></div><label class="checkbox-label"><input name="covenant" type="checkbox" required>我已阅读并接受领养公约，包括回访与 0–5 星评价展示。</label><label class="checkbox-label"><input name="privacy" type="checkbox" required>同意平台保存账号资料与确认后的生活画像；语音访谈使用 AI 服务处理。姓名与联系方式不在主页公开。</label><p class="footnote">注册后默认接收宠物 AI 分身的站内招呼，可随时在消息页关闭。</p><p id="register-error" role="alert" class="form-error"></p><button class="button primary full">同意公约，进入下一步语音访谈 ${icon('arrow')}</button></form>${button('已有账号，去登录','adopter-login','text-button full spaced')}<div class="join-station">救助站账号由平台人工开通</div></main>`;
}
export function loginView({topbar,button}){return `${topbar('欢迎回来','登录你的领养者账号')}<main class="main"><div class="join-hero"><h1>继续认识，<br>继续陪伴。</h1></div><form id="adopter-login-form" class="form-stack"><label>登录账号<input name="username" required autocomplete="username" autocapitalize="none"></label><label>密码<input name="password" type="password" required autocomplete="current-password"></label><p class="form-error" role="alert"></p><button class="button primary full">登录</button></form>${button('还没有账号，前往注册','register','text-button full spaced')}</main>`;}
export function interviewView(c){
 const {topbar,esc,icon,button,questions,answers,analysis,step,review,viewing,registering,busy,error,turns=[],text,audioUrl,voiceOpen=false}=c;
 const label=key=>questions.find(q=>q.key===key)?.label||key;
 if(review)return `${topbar(viewing?'我的生活名片':'这是你的生活名片',viewing?'可以重新聊聊，更新你的资料':registering?'核对后，再完成注册':'核对后，更新你的生活资料')}<main class="main lifestyle-page"><div class="persona-hero"><span>${icon('spark')}</span><p>YOUR LITTLE PAWSONALITY</p><h1>${esc(analysis?.title||'正在认真认识你')}</h1><p>${esc(analysis?.summary||'把刚才聊到的生活整理成一张名片。')}</p></div>${analysis?`<div class="persona-highlights">${analysis.highlights.map(t=>`<span>${esc(t)}</span>`).join('')}</div><h2 class="persona-section">可以优先认识它们</h2>${analysis.recommendations.map(r=>`<article class="persona-recommendation"><h3>${esc(r.type)}</h3><p>${esc(r.reason)}</p><small>依据：${r.basedOn.map(label).map(esc).join('、')}</small></article>`).join('')}<p class="footnote">这是基于当前回答的认识方向，具体仍要看每只宠物的性格、照护需求和救助站的观察。</p>${analysis.unknowns.length?`<div class="info-box"><div><strong>还可以慢慢了解</strong><p>${analysis.unknowns.map(esc).join('；')}</p></div></div>`:''}`:''}<details class="persona-details"><summary>查看刚才聊到的内容 · 修改</summary>${questions.map((q,i)=>`<div class="lifestyle-answer"><h3>${esc(q.label)}</h3><p>${esc(answers[q.key]?.text||'待了解')}</p>${button('再聊这一项','lifestyle-edit','text-button',String(i))}</div>`).join('')}</details>${error?`<p role="alert" class="form-error">${esc(error)}</p>`:''}${!analysis?button(busy?'正在整理…':'重新整理生活名片','lifestyle-summary','button primary full','',busy?'disabled':''):viewing?button('重新聊聊，更新画像','lifestyle-restart','button primary full'):button(busy?'正在保存…':registering?'确认画像，完成注册':'确认并保存画像','lifestyle-confirm','button primary full','',busy?'disabled':'')}<p class="footnote">生活画像仅本人可见，提交申请前会请你确认向负责站点分享。</p></main>`;
 const history=questions.slice(0,step+1).map((q,index)=>{
  const entries=turns.filter(turn=>turn.step===index);
  const prompt=`<div class="interview-bubble agent"><span class="interview-agent-mark">${icon('spark')} 领养助手</span><p>${esc(q.title)}</p><small>${esc(q.hint)}</small></div>`;
  const replies=entries.length?entries.map(turn=>`<div class="interview-bubble human">${esc(turn.text)}</div>${turn.reply?`<div class="interview-bubble agent">${esc(turn.reply)}</div>`:''}`).join(''):index<step&&answers[q.key]?.text?`<div class="interview-bubble human">${esc(answers[q.key].text)}</div>`:'';
  return prompt+replies;
 }).join('');
 return `${topbar('和领养助手聊聊',`认识你的日常 · ${Math.min(step+1,4)} / 4`)}<main class="interview-page"><div class="interview-stream">${history}</div><div class="interview-composer"><div id="interview-live" class="interview-live" role="status" ${!voiceOpen&&!busy?'hidden':''}>${busy?'正在听懂你的回答…':'按住说话，松手发送；上滑取消。'}</div>${error?`<p role="alert" class="form-error">${esc(error)}</p>${audioUrl?`<audio controls src="${esc(audioUrl)}"></audio>${button('重新转写','lifestyle-transcribe','text-button')}`:''}`:''}<form id="lifestyle-answer-form" class="interview-text"><textarea id="lifestyle-answer" name="answer" rows="1" maxlength="2000" placeholder="说说你的日常…" ${busy?'disabled':''}>${esc(text)}</textarea><button type="button" data-action="interview-voice-toggle" class="interview-voice-toggle" aria-label="${voiceOpen?'收起语音输入':'展开语音输入'}" aria-expanded="${voiceOpen}" aria-controls="interview-voice-panel" ${busy?'disabled':''}>${icon('mic')}</button><button type="submit" aria-label="发送回答" ${busy?'disabled':''}>${icon('send')}</button></form><div id="interview-voice-panel" class="interview-voice-panel" ${voiceOpen?'':'hidden'}><button id="interview-hold" class="interview-hold" type="button" ${busy?'disabled':''} aria-label="按住说话，松手发送，上滑取消">${icon('mic')}<span>按住说话</span></button><p class="footnote">最长 60 秒 · 松手发送后由 AI 理解，最后统一确认</p></div></div></main>`;
}
